import z from "@deepseek-ai/schemastery";
const name = "dsh-url-printer";
const inject = ["webServer", "connection"];
const Config = z.object({});
function apply(ctx) {
  const printUrl = () => {
    const port = ctx.webServer?.port;
    if (port === undefined) return;
    const base = `http://127.0.0.1:${port}`;
    let url = base;
    try {
      url = ctx.connection.authenticatedUrl(base);
    } catch (error) {
      console.log(`dsh web: ${base} (authenticated url unavailable: ${String(error)})`);
      return;
    }
    console.log(`dsh web: ${url}`);
  };
  const settled = ctx.get("loader")?.await();
  if (settled === undefined) printUrl();
  else settled.then(() => { if (ctx.get("webServer") !== undefined) printUrl(); }, () => {});
}
export { Config, apply, inject, name };
